def skill():
    return 20 + 4 * (-(12 - 10) / 2)

def standard():
    k = Symbol('k')
    # P(X<=12)=Phi(1) , P(Y>=k)=1-Phi((k-20)/4); 같으려면 (k-20)/4 = -1
    from sympy import erf
    Phi = lambda z: (1 + erf(z / sqrt(2))) / 2
    target = Phi(Rational(12 - 10, 2))
    val = nsolve(1 - Phi((k - 20) / 4) - target, k, 15)
    return int(round(float(val)))

def unique():
    return [standard()]
